nav.onclick=e=>{const b=e.target.closest('[data-reg-jump]');if(b)jump(b.dataset.regJump);};$('#code').onclick=e=>{const b=e.target.closest('[data-reg-code]');if(b){selected=b.dataset.regCode;focus=Number(b.dataset.line);renderCode();}};tabs.onclick=e=>{const b=e.target.closest('[data-reg-view]');if(b){s.view=b.dataset.regView;focus=null;codeMode='full';selected=s.view==='traditional'?'ols':s.view==='regularization'?'regularization':'evaluation';render();}};$('#inputs').addEventListener('input',e=>{if(e.target.id==='regLog')$('#reg-lambda').value=10**Number(e.target.value);if(e.target.matches('input'))render();});
